static bool IsAnagram(string s, string t) {
    if (s.Length != t.Length) return false;
    Span<int> counts = stackalloc int[26];   // 104 bytes on the stack, 0 B on the heap
    counts.Clear();
    for (int i = 0; i < s.Length; i++) {
        counts[s[i] - 'a']++;                // only 'a'..'z' — clarify the constraints
        counts[t[i] - 'a']--;
    }
    foreach (int c in counts) if (c != 0) return false;
    return true;
}

