[BurstCompile]
struct SumCostJob : IJob {
    [ReadOnly] public NativeArray<int> cost;   // grid cell costs
    public NativeArray<long> result;           // a single slot for the answer
    public void Execute() {
        long s = 0;
        for (int i = 0; i < cost.Length; i++) s += cost[i];
        result[0] = s;
    }
}

var cost = new NativeArray<int>(512 * 512, Allocator.TempJob);
var result = new NativeArray<long>(1, Allocator.TempJob);
new SumCostJob { cost = cost, result = result }.Schedule().Complete();
long total = result[0];
cost.Dispose(); result.Dispose();
